swift - <<'SWIFT'
import Foundation
import ApplicationServices
let pid: pid_t = 804
let app = AXUIElementCreateApplication(pid)
var value: CFTypeRef?
let err = AXUIElementCopyAttributeValue(app, kAXWindowsAttribute as CFString, &value)
print("err", err)
if let windows = value as? [AXUIElement] {
  print("windows", windows.count)
  for w in windows {
    var title: CFTypeRef?
    AXUIElementCopyAttributeValue(w, kAXTitleAttribute as CFString, &title)
    print("window title", title ?? "nil")
    var children: CFTypeRef?
    AXUIElementCopyAttributeValue(w, kAXChildrenAttribute as CFString, &children)
    if let kids = children as? [AXUIElement] {
      print("kids", kids.count)
    }
  }
}
SWIFT

